package com.bank.sched.dynamic;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import java.util.concurrent.atomic.AtomicReference;

@Component
public class CronProvider {

    private final AtomicReference<String> cron = new AtomicReference<>();

    public CronProvider(@Value("${scheduler.statement-cron}") String initialCron) {
        this.cron.set(initialCron);
    }

    public String currentCron() { return cron.get(); }          // read at runtime
    public void updateCron(String newCron) { cron.set(newCron); } // change at runtime
}
