// FIX #3: schedule programmatically with a CronTrigger that RE-READS the cron each time
package com.bank.sched.dynamic;

import jakarta.annotation.PostConstruct;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.scheduling.TaskScheduler;
import org.springframework.scheduling.support.CronTrigger;
import org.springframework.stereotype.Service;
import java.time.Instant;
import java.util.concurrent.ScheduledFuture;

@Service
@RequiredArgsConstructor
@Slf4j
public class DynamicCronService {

    private final TaskScheduler taskScheduler;
    private final CronProvider cronProvider;
    private volatile ScheduledFuture<?> future;

    @PostConstruct
    public void start() { reschedule(); }

    // Reschedule at runtime: cancel the old future and schedule a trigger that reads the current cron
    public synchronized void reschedule() {
        if (future != null) future.cancel(false);
        future = taskScheduler.schedule(this::runStatementJob, triggerContext -> {
            String cron = cronProvider.currentCron();            // READ DYNAMICALLY each computation
            return new CronTrigger(cron).nextExecution(triggerContext);
        });
        log.info("(Re)scheduled statement job with cron '{}'", cronProvider.currentCron());
    }

    // Compute the next execution for a given cron — used by tests and the API preview
    public Instant previewNext(String cron) {
        var ctx = new org.springframework.scheduling.support.SimpleTriggerContext();
        var next = new CronTrigger(cron).nextExecution(ctx);
        return next;
    }

    private void runStatementJob() {
        log.info("Running statement job on thread {}", Thread.currentThread().getName());
        // ... delegate to a service ...
    }
}
