// Multiple @Scheduled jobs — with the pool (fix #1) they no longer block each other
package com.bank.sched.job;

import lombok.extern.slf4j.Slf4j;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
@Slf4j
public class BatchJobs {

    // A long job — on the DEFAULT single thread this would block the others
    @Scheduled(fixedRate = 60_000)
    public void slowReconciliation() throws InterruptedException {
        log.info("Reconciliation START on {}", Thread.currentThread().getName());
        Thread.sleep(2000);   // simulate long work
        log.info("Reconciliation END");
    }

    // A quick heartbeat — with the pool it runs even while reconciliation is busy
    @Scheduled(fixedRate = 5_000)
    public void heartbeat() {
        log.info("Heartbeat on {}", Thread.currentThread().getName());
    }

    // LIMITATION #2 reminder (no persistence): if the app is down at this cron time,
    // the run is simply MISSED — no catch-up. Must-not-miss jobs belong in Quartz (JDBC store).
    @Scheduled(cron = "0 0 2 * * *")
    public void regulatoryExtract() {
        log.info("Regulatory extract on {}", Thread.currentThread().getName());
    }
}
