package com.bank.sched.controller;

import com.bank.sched.dynamic.CronProvider;
import com.bank.sched.dynamic.DynamicCronService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.util.Map;

@RestController
@RequestMapping("/api/v1/scheduler")
@RequiredArgsConstructor
public class SchedulerController {

    private final CronProvider cronProvider;
    private final DynamicCronService dynamicCronService;

    // FIX #3: change the schedule at RUNTIME without a redeploy
    @PutMapping("/statement-cron")
    public Map<String, Object> reschedule(@RequestParam String cron) {
        cronProvider.updateCron(cron);     // update the dynamic source
        dynamicCronService.reschedule();   // re-arm the trigger with the new cron
        return Map.of("newCron", cron, "nextRun", dynamicCronService.previewNext(cron).toString());
    }

    @GetMapping("/statement-cron")
    public Map<String, Object> current() {
        String cron = cronProvider.currentCron();
        return Map.of("cron", cron, "nextRun", dynamicCronService.previewNext(cron).toString());
    }
}
