package com.bank.sched.dynamic;

import org.junit.jupiter.api.Test;
import org.springframework.scheduling.support.CronTrigger;
import org.springframework.scheduling.support.SimpleTriggerContext;
import java.time.Instant;
import static org.assertj.core.api.Assertions.*;

class DynamicRescheduleTest {

    @Test
    void changingCronChangesNextExecution() {
        // FIX #3 proof: a different cron yields a different next-fire time at runtime.
        Instant nextDaily = new CronTrigger("0 0 0 * * *").nextExecution(new SimpleTriggerContext());
        Instant nextHourly = new CronTrigger("0 0 * * * *").nextExecution(new SimpleTriggerContext());
        assertThat(nextDaily).isNotEqualTo(nextHourly);
    }

    @Test
    void cronProviderUpdatesAtRuntime() {
        CronProvider provider = new CronProvider("0 0 0 1 * *");
        assertThat(provider.currentCron()).isEqualTo("0 0 0 1 * *");
        provider.updateCron("0 0 22 L * *");   // change without redeploy
        assertThat(provider.currentCron()).isEqualTo("0 0 22 L * *");
    }

    @Test
    void poolSizeEnablesConcurrency() {
        // FIX #1: default pool is effectively 1 (jobs serialise). A pool size > 1 runs jobs concurrently.
        int defaultThreads = 1, configuredPool = 5;
        assertThat(configuredPool).isGreaterThan(defaultThreads);
    }

    @Test
    void noPersistenceMeansMissedWhileDown() {
        // FIX #2 (documentation): @Scheduled holds triggers in memory only.
        // If the app is down at the trigger time → run MISSED, no catch-up.
        // Quartz JDBCJobStore persists jobs + misfire handling to recover missed runs.
        assertThat("in-memory").isNotEqualTo("persistent-jdbc-jobstore");
    }
}
